import { Blocker } from 'react-router-dom';
import { openWebview } from '~/shared/api/web-view';
import i18n from '~/shared/i18n/i18n';
import { overlay } from '~/shared/lib/overlay';
import { PATHS } from '~/shared/routes/paths';
import { Dialog } from '~/shared/ui/dialogs/dialog';

export const useWalletMissingAlert = () => {
  const showAlert = (blocker?: Blocker) => {
    overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
      return (
        <Dialog
          afterLeave={unmount}
          open={isOpen}
          onClose={close}
          message={i18n.t('text:walletCreationRequired')}
          buttonLabel={[i18n.t('cancel'), i18n.t('createWallet')]}
          onConfirmClick={() => {
            blocker?.proceed?.();
            openWebview(PATHS.issueWallet.intro);
          }}
          onCancelClick={() => {
            blocker?.reset?.();
          }}
        />
      );
    });
  };

  return { showAlert };
};
