import { memo, useCallback, useEffect } from 'react';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';

type NavigationProps = {
  onBack?: () => void;
  headerTitle?: string;
  headerRight?: React.ReactNode;
  headerLeft?: React.ReactNode;
};

export const Navigation = memo(function Navigation({ onBack, headerTitle, headerRight, headerLeft }: NavigationProps) {
  const { navigate, navigateBack } = useNavigate();

  const handleBack = useCallback(() => {
    if (onBack) {
      onBack();
      return;
    }

    navigateBack();
  }, []);

  useEffect(() => {
    window.navigateBack = handleBack;
  }, [handleBack, navigate]);

  return (
    <header className="common-header">
      {headerLeft || (
        <button onClick={handleBack} type="button" className="btn-go-main">
          메인으로
        </button>
      )}
      {headerRight}
    </header>
  );
});
