import clsx from 'clsx';
import { forwardRef } from 'react';
import { LabelProps, OnClickProps } from './types';

export const RadioLabel = forwardRef<HTMLLIElement, LabelProps<unknown>>(
  ({ option, isSelected, onClick }, ref) => (
    <li ref={ref} className={clsx('period-select-item', { 'is-selected': isSelected })}>
      <button
        type="button"
        className="btn-period-option"
        aria-selected={isSelected}
        onClick={(e) =>
          onClick({
            event: e as unknown as React.MouseEvent<HTMLInputElement>,
            option,
          } as OnClickProps<unknown>)
        }
        disabled={option.disabled}
      >
        <span className="period-text">{option.label}</span>
        {isSelected && <i className="icon-check-arrow" aria-hidden="true"></i>}
      </button>
    </li>
  ),
);

RadioLabel.displayName = 'RadioLabel';
