import qs from 'qs';
import { useStore } from '~/app/store/store';
import { UtilEvents } from '~/entities/app-config/model/store';
import { CURRENT_URL } from '~/shared/config/url';
import { NativeFunction } from '~/shared/constants/native-function';
import { PathType } from '~/shared/routes/paths';

// ======================================
// WebView Navigation
// ======================================

/**
 * 웹뷰를 열고 새 페이지를 로드합니다.
 */
export const openWebview = (url: PathType, param?: any) => {
  let targetUrl = `${CURRENT_URL}${url}`;

  // 파라미터에 isChildWindow 추가
  const allParams = { ...param, isChildWindow: true };
  const queryString = qs.stringify(allParams);

  if (targetUrl.includes('?')) {
    targetUrl = `${targetUrl}&${queryString}`;
  } else {
    targetUrl = `${targetUrl}?${queryString}`;
  }

  if (!window.ReactNativeWebView) {
    // 새 창을 띄울 경우 매번 새로운 id를 부여합니다.
    const uniqueWindowName = `window_${Date.now()}_${Math.random().toString(36).substring(2, 10)}`;
    window.open(targetUrl, uniqueWindowName);
    return;
  }

  // window.webViewBridge.send(NativeFunction.OpenWebview, targetUrl);
  window.ReactNativeWebView.postMessage(
    JSON.stringify({
      targetFunc: 'openWebview',
      data: targetUrl,
      isPopup: true,
    }),
  );
};

/**
 * 웹뷰를 닫습니다.
 */
export const closeWebview = (props: UtilEvents = {}) => {
  const { redirectPath, notiBarMessage, snackBarMessage } = props;

  // 리다이렉트 경로와 메시지 설정
  if (redirectPath) {
    const setRedirectPath = useStore.getState().appConfigSlice.setRedirectPath;
    setRedirectPath(redirectPath);
  }

  // 메시지 설정
  if (notiBarMessage || snackBarMessage) {
    setMessages({ notiBarMessage, snackBarMessage });
  }

  // 웹뷰 닫기
  if (!window.ReactNativeWebView) {
    window.close();
    return;
  }
  window.webViewBridge.send(NativeFunction.GoBack);
  //window.history.back();
};

/**
 * 웹뷰에서 뒤로가기 동작을 처리합니다.
 */
export const goBackWebview = (goBack: () => void, fallback?: () => void) => {
  const fallbackOnce = () => {
    if (fallback) {
      fallback();
      return;
    }
    if (!window.ReactNativeWebView) {
      window.close(); // 브라우저 접속 시 fallback
      return;
    }
    window.webViewBridge?.send?.('CLOSE_POPUP');
  };

  if (!window.ReactNativeWebView) {
    if (window.history.length > 1) {
      goBack();
      return;
    }
    fallbackOnce();
    return;
  }

  if (!window.webViewBridge?.send) {
    fallbackOnce();
    return;
  }

  let didRespond = false;
  const timeoutId = window.setTimeout(() => {
    if (!didRespond) {
      fallbackOnce();
    }
  }, 400);

  window.webViewBridge.send(NativeFunction.CanGoBack, {
    success: (res: any) => {
      didRespond = true;
      window.clearTimeout(timeoutId);
      if (res?.data && window.history.length > 1) {
        goBack();
        return;
      }
      fallbackOnce();
    },
  });
};

/**
 * 알림 메시지와 스낵바 메시지를 Zustand 스토어에 설정합니다.
 */
export const setMessages = ({
  notiBarMessage,
  snackBarMessage,
}: Pick<UtilEvents, 'notiBarMessage' | 'snackBarMessage'>) => {
  const store = useStore.getState();
  const setNotiBarMessage = store.appConfigSlice.setNotiBarMessage;
  const setSnackBarMessage = store.appConfigSlice.setSnackBarMessage;

  if (notiBarMessage) {
    setNotiBarMessage(notiBarMessage);
  }

  if (snackBarMessage) {
    setSnackBarMessage(snackBarMessage);
  }
};
