import { useEffect } from 'react';
import { clearAuthData, kickOut } from '~/features/logout-and-clear-data/lib/clear-app-data';
import { CBDCAxiosFallbackProps } from '~/shared/@types/error';
import { useErrorMessage } from '~/shared/lib/hooks/error/use-error-message';
import { Dialog } from '~/shared/ui/dialogs/dialog';

export const NetworkErrorFallback = ({ error, resetErrorBoundary }: CBDCAxiosFallbackProps) => {
  useEffect(() => {
    console.error('[ErrorBoundary] Network Error', JSON.stringify(error.response?.data));
    clearAuthData();
  }, [error]);

  const { formatErrorMessage } = useErrorMessage();
  const errorMessage = formatErrorMessage(error);

  const handleCancel = () => {
    resetErrorBoundary?.();
  };

  const handleConfirm = () => {
    resetErrorBoundary?.();
    kickOut();
  };

  return (
    <Dialog
      afterLeave={() => null}
      open={true}
      onClose={() => null}
      onConfirmClick={handleConfirm}
      onCancelClick={handleCancel}
      message={errorMessage.message}
    />
  );
};
