import { ReactNode, useEffect } from 'react';
import { useOutletContext } from 'react-router-dom';
import { ContextType } from '.';

export const useSubLayoutContext = () => {
  return useOutletContext<ContextType>();
};

export const useSetOnBack = (fn: any) => {
  const { setOnBack } = useSubLayoutContext();
  useEffect(() => {
    setOnBack(() => fn);
    return () => {
      setOnBack(() => undefined);
    };
  }, [setOnBack]);
  return { setOnBack };
};

export const useSetHeaderTitle = (title: string) => {
  const { setHeaderTitle } = useSubLayoutContext();
  useEffect(() => {
    setHeaderTitle(title);
    return () => setHeaderTitle('');
  }, [setHeaderTitle]);
  return { setHeaderTitle };
};

export const useSetHeaderRight = (component: ReactNode, ...args: any[]) => {
  const { setHeaderRight } = useSubLayoutContext();
  useEffect(() => {
    setHeaderRight(component);
    return () => setHeaderRight(undefined);
  }, [setHeaderRight, ...args]);
  return { setHeaderRight };
};

export const useSetHeaderLeft = (component: ReactNode, ...args: any[]) => {
  const { setHeaderLeft } = useSubLayoutContext();
  useEffect(() => {
    setHeaderLeft(component);
    return () => setHeaderLeft(undefined);
  }, [setHeaderLeft, ...args]);
  return { setHeaderLeft };
};

export const useSetIsPullToRefreshEnabled = (enabled: boolean) => {
  const { setIsPullToRefreshEnabled } = useSubLayoutContext();
  useEffect(() => {
    setIsPullToRefreshEnabled(enabled);
    return () => setIsPullToRefreshEnabled(false);
  }, [setIsPullToRefreshEnabled, enabled]);
  return { setIsPullToRefreshEnabled };
};
