// 클라이언트에서만 사용되는 필드 (서버 응답에 없는 필드)
export const clientOnlyFieldsSchema = z.object({
  tokenList: z.array(tokenItemSchema).nullable(),
  isWalletBlocked: z.boolean().optional(), // 지갑 블록 여부
  hasWallet: z.boolean().optional(), // 지갑 존재 여부
});

// 기본 타입 정의
export type ServerUserParams = z.infer<typeof serverUserParamsSchema>;
export type ClientOnlyFields = z.infer<typeof clientOnlyFieldsSchema>;

// 서버와 클라이언트 필드가 확장된 통합 사용자 파라미터 타입
export const extendedUserParamsSchema = serverUserParamsSchema.extend(clientOnlyFieldsSchema.shape);
export type ExtendedUserParams = z.infer<typeof extendedUserParamsSchema>;

// 서버 데이터 응답 스키마
export const serverResponseSchema = z.object({
  tbCstmrMastr: serverUserParamsSchema,
  transkeyModel: z.any().nullable(),
  editable: z.boolean(),
});

export type ServerResponse = z.infer<typeof serverResponseSchema>;

// 전체 사용자 응답 스키마 (서버 + 클라이언트)
export const userResponseSchema = z
  .object({
    tbCstmrMastr: extendedUserParamsSchema,
    transkeyModel: z.any().nullable(),
    editable: z.boolean(),
  })
  .passthrough();

export type UserResponse = z.infer<typeof userResponseSchema>;

// 사용자 지갑 정보 타입 (userResponseSchema에서 tbCstmrMastr 필드만 추출)
export type UserWalletResponse = z.infer<typeof userResponseSchema>['tbCstmrMastr'];

// 사용자 등록 응답 스키마
export type CreateUserResponse = z.infer<typeof createUserSchema>;

// 부분 업데이트를 위한 스키마
export const partialUserDataSchema = userResponseSchema.partial();

// 서버 데이터 검증 함수
export function validateServerData(data: unknown): ServerResponse {
  const parsed = serverResponseSchema.safeParse(data);
  if (parsed.success) {
    return parsed.data;
  } else {
    throw new Error('서버 데이터 검증 실패: ' + parsed.error.message);
  }
}

// 전체 사용자 데이터 검증 함수
export function validateUserData(data: unknown): UserResponse {
  return userResponseSchema.parse(data);
}

// 부분 업데이트를 위한 검증 함수
export function validatePartialUserData(data: unknown): Partial<UserResponse> {
  return partialUserDataSchema.parse(data) as Partial<UserResponse>;
}
