import * as Sentry from '@sentry/react';
import { createBrowserRouter, createRoutesFromElements, Navigate, Route } from 'react-router-dom';
import { Account } from '~/pages/account/account-routes';
import { Biometric } from '~/pages/biometric/biometric-routes';
import { Community } from '~/pages/community/community-routes';
import { Exchange } from '~/pages/exchange/exchange-routes';
import { Confirm } from '~/pages/issue-wallet/confirm';
import { IssueWallet } from '~/pages/issue-wallet/issue-wallet-routes';
import { MyWallet } from '~/pages/my-wallet/my-wallet-routes';
import { Notifi } from '~/pages/notification/notification-routes';
import { Payment } from '~/pages/payment/payment-routes';
import { Pin } from '~/pages/pin/pin-routes';
import { SetAutoOnOffRamp } from '~/pages/set-auto-on-off-ramp/set-auto-on-off-ramp-routes';
import { SetOffRamp } from '~/pages/set-auto-on-off-ramp/set-off-ramp/set-off-ramp-routes';
import { SignUp } from '~/pages/sign-up/sign-up-routes';
import { Voucher } from '~/pages/voucher/voucher-routes';
import { ErrorBoundaryWrapper } from '~/widgets/error-boundaries';
import { NotFoundErrorFallback } from '~/widgets/fallbacks';
import { ProtectedRoute } from '~/widgets/protected-route';
import { TestProtectedRoute } from '~/widgets/protected-route/test-protected-route';
import { PullToRefreshRoute } from '~/widgets/pull-to-refresh/pull-to-refresh-route';
import { RootLayout } from '~/widgets/root-layout';
import { SubLayout } from '~/widgets/sub-layout';
import { PATHS } from '~/shared/routes/paths';
import { ROUTE_NAMES } from '~/shared/routes/route-names';
import { Root } from './routes';

const sentryCreateBrowserRouter = Sentry.wrapCreateBrowserRouter(createBrowserRouter);

export const router = sentryCreateBrowserRouter(
  createRoutesFromElements(
    <Route path={ROUTE_NAMES.root} element={<RootLayout />} errorElement={<ErrorBoundaryWrapper />}>
      <Route index element={<Navigate replace to={PATHS.intro} />} />
      <Route path={ROUTE_NAMES.intro} lazy={Root.intro.lazy} />

      <Route element={<TestProtectedRoute />}>
        <Route path={ROUTE_NAMES.superAppSample} lazy={Root.superAppSample.lazy} />
      </Route>

      <Route element={<SubLayout />}>
        <Route path={ROUTE_NAMES.mobileVerification} lazy={Root.mobileVerification.lazy} />

        <Route path={ROUTE_NAMES.signUp.base}>
          <Route path={ROUTE_NAMES.signUp.termsAndConditions} lazy={SignUp.termsAndConditions.lazy} />
          <Route path={ROUTE_NAMES.signUp.arsNumber} lazy={SignUp.arsNumber.lazy} />
        </Route>

        <Route path={ROUTE_NAMES.account.base}>
          <Route path={ROUTE_NAMES.account.verifyBank} lazy={Account.verifyBank.lazy} />
          <Route path={ROUTE_NAMES.account.myBankAccount} lazy={Account.myBankAccount.lazy} />
        </Route>

        <Route path={ROUTE_NAMES.pin.base}>
          <Route path={ROUTE_NAMES.pin.set} lazy={Pin.set.lazy} />
          <Route path={ROUTE_NAMES.pin.input} lazy={Pin.input.lazy} />
          <Route path={ROUTE_NAMES.pin.reset} lazy={Pin.reset.lazy} />
          <Route path={ROUTE_NAMES.pin.login} lazy={Pin.login.lazy} />

          <Route path={ROUTE_NAMES.pin.business} lazy={Pin.business.lazy} />
        </Route>

        <Route path={ROUTE_NAMES.biometric.base}>
          <Route path={ROUTE_NAMES.biometric.set} lazy={Biometric.set.lazy} />
          <Route path={ROUTE_NAMES.biometric.reset} lazy={Biometric.reset.lazy} />
        </Route>

        <Route element={<ProtectedRoute />}>
          <Route path={ROUTE_NAMES.issueWallet.base}>
            <Route path={ROUTE_NAMES.issueWallet.intro} lazy={IssueWallet.intro.lazy} />
            <Route path={ROUTE_NAMES.issueWallet.inputBankAccount} lazy={IssueWallet.inputBankAccount.lazy} />
            <Route path={ROUTE_NAMES.issueWallet.authBankAccount} lazy={IssueWallet.authBankAccount.lazy} />
            <Route path={ROUTE_NAMES.issueWallet.chooseIDCardType} lazy={IssueWallet.chooseIDCardType.lazy} />
            <Route
              path={ROUTE_NAMES.issueWallet.captureBusinessLicense}
              lazy={IssueWallet.captureBusinessLicense.lazy}
            />

            <Route path={ROUTE_NAMES.issueWallet.confirm.base}>
              <Route path={ROUTE_NAMES.issueWallet.confirm.IDCard} lazy={Confirm.IDCard.lazy} />
              <Route path={ROUTE_NAMES.issueWallet.confirm.driverLicense} lazy={Confirm.driverLicense.lazy} />
              <Route path={ROUTE_NAMES.issueWallet.confirm.passport} lazy={Confirm.passport.lazy} />
              <Route path={ROUTE_NAMES.issueWallet.confirm.businessLicense} lazy={Confirm.businessLicense.lazy} />
            </Route>
          </Route>

          <Route path={ROUTE_NAMES.myWallet.base}>
            <Route index lazy={MyWallet.manageWallet.lazy} />
            <Route path={ROUTE_NAMES.myWallet.manageWallet} lazy={MyWallet.manageWallet.lazy} />
            <Route path={ROUTE_NAMES.myWallet.history} lazy={MyWallet.history.lazy} />
            <Route path={ROUTE_NAMES.myWallet.historyDetail} lazy={MyWallet.historyDetail.lazy} />
            <Route path={ROUTE_NAMES.myWallet.refundQRCode} lazy={MyWallet.refundQRCode.lazy} />

            <Route path={ROUTE_NAMES.myWallet.business} lazy={MyWallet.business.lazy} />
          </Route>

          <Route path={ROUTE_NAMES.exchange.base}>
            <Route index lazy={Exchange.root.lazy} />
          </Route>

          <Route path={ROUTE_NAMES.security} lazy={Root.security.lazy} />
          <Route path={ROUTE_NAMES.settingFontSize} lazy={Root.settingFontSize.lazy} />
          <Route path={ROUTE_NAMES.setAutoOnOffRamp.base}>
            <Route path={ROUTE_NAMES.setAutoOnOffRamp.root} lazy={SetAutoOnOffRamp.root.lazy} />
            <Route path={ROUTE_NAMES.setAutoOnOffRamp.setOnRamp} lazy={SetAutoOnOffRamp.setOnRamp.lazy} />

            <Route path={ROUTE_NAMES.setAutoOnOffRamp.setOffRamp.base}>
              <Route path={ROUTE_NAMES.setAutoOnOffRamp.setOffRamp.root} lazy={SetOffRamp.root.lazy} />
              <Route path={ROUTE_NAMES.setAutoOnOffRamp.setOffRamp.setThreshold} lazy={SetOffRamp.setThreshold.lazy} />
            </Route>
          </Route>
          {/* <Route path={ROUTE_NAMES.settingThreshold} lazy={Root.settingThreshold.lazy} /> */}

          <Route path={ROUTE_NAMES.community.base}>
            <Route path={ROUTE_NAMES.community.faq} lazy={Community.faq.lazy} />
            <Route path={ROUTE_NAMES.community.faqDetail} lazy={Community.faqDetail.lazy} />
            <Route path={ROUTE_NAMES.community.notice} lazy={Community.notice.lazy} />
            <Route path={ROUTE_NAMES.community.noticeDetail} lazy={Community.noticeDetail.lazy} />
            <Route path={ROUTE_NAMES.community.inquiry} lazy={Community.inquiry.lazy} />
            <Route path={ROUTE_NAMES.community.inquiryDetail} lazy={Community.inquiryDetail.lazy} />
            <Route path={ROUTE_NAMES.community.inquiryModify} lazy={Community.inquiryModify.lazy} />
          </Route>

          <Route path={ROUTE_NAMES.shopList} lazy={Root.shopList.lazy} />

          <Route path={ROUTE_NAMES.notification.base}>
            <Route index lazy={Notifi.list.lazy} />
            <Route path={ROUTE_NAMES.notification.list} lazy={Notifi.list.lazy} />
            <Route path={ROUTE_NAMES.notification.setting} lazy={Notifi.setting.lazy} />
          </Route>

          <Route path={ROUTE_NAMES.payment.base}>
            <Route path={ROUTE_NAMES.payment.myPaymentQRCode} lazy={Payment.myPaymentQRCode.lazy} />
          </Route>

          <Route path={ROUTE_NAMES.qrScan} lazy={Root.qrScan.lazy} />
          <Route path={ROUTE_NAMES.menu} lazy={Root.menu.lazy} />

          <Route path={ROUTE_NAMES.voucher.base}>
            <Route index lazy={Voucher.list.lazy} />
            <Route path={ROUTE_NAMES.voucher.list} lazy={Voucher.list.lazy} />
            <Route path={ROUTE_NAMES.voucher.allVoucher} lazy={Voucher.allVoucher.lazy} />
            <Route path={ROUTE_NAMES.voucher.voucherDetail} lazy={Voucher.voucherDetail.lazy} />
          </Route>
        </Route>

        <Route path="*" element={<NotFoundErrorFallback />} />
      </Route>
      <Route path={ROUTE_NAMES.pwFail} lazy={Root.pwFail.lazy} />

      <Route element={<PullToRefreshRoute />}>
        <Route element={<ProtectedRoute />}>
          <Route path={ROUTE_NAMES.home} lazy={Root.home.lazy} />
        </Route>
      </Route>

      <Route path={ROUTE_NAMES.paymentGuide} lazy={Root.paymentGuide.lazy} />
      <Route path={ROUTE_NAMES.inputTransactionNumber} lazy={Root.inputTransactionNumber.lazy} />
    </Route>,
  ),
);
