import { RouteConfig } from '~/shared/routes/route-names';

export const Biometric: RouteConfig<'biometric'> = {
  set: {
    lazy: async () => {
      const { SetBiometricPage } = await import('./set-biometric/set-biometric-page');
      return {
        Component: SetBiometricPage,
      };
    },
  },
  reset: {
    lazy: async () => {
      const { ResetBiometricPage } = await import('./reset-biometric/reset-biometric-page');
      return {
        Component: ResetBiometricPage,
      };
    },
  },
};
