export type DialogButtonsProps = {
  buttonLabel: string[];
  onConfirm: () => void;
  onCancel: () => void;
};

export const DialogButtons = ({ buttonLabel, onConfirm, onCancel }: DialogButtonsProps) => {
  if (buttonLabel.length === 1) {
    return (
      <button className="btm-btn app rounded-b-[10px]" onClick={onConfirm}>
        {buttonLabel[0]}
      </button>
    );
  }
  return (
    <div className="alert-btn confirm">
      {buttonLabel[0] && (
        <button className="btm-btn rounded-bl-[10px]" onClick={onCancel}>
          {buttonLabel[0]}
        </button>
      )}
      {buttonLabel[1] && (
        <button className="btm-btn app rounded-br-[10px]" onClick={onConfirm}>
          {buttonLabel[1]}
        </button>
      )}
    </div>
  );
};
