import ReactDOM from 'react-dom/client';
import '~/shared/assets/styles/index.scss';
import { initAxios } from '~/shared/config/axios';
import { App } from './entrypoint/app';
import { AppProvider } from './entrypoint/app-provider';
import 'abortcontroller-polyfill/dist/abortsignal-polyfill-only';

const initApp = async () => {
  initAxios();
  try {
    const { initMSW } = await import('~/__mocks__');
    await initMSW();
  } catch (e) {
    //console.log('개발 환경에서만 동작합니다', e);
    return null;
  }
};

(async () => {
  await initApp();
  const root = ReactDOM.createRoot(document.getElementById('root') as HTMLElement);
  root.render(
    <>
      {/* <React.StrictMode> */}
      <AppProvider>
        <App />
      </AppProvider>
      {/* </React.StrictMode> */}
    </>,
  );
  // If you want to start measuring performance in your app, pass a function
  // to log results (for example: reportWebVitals(console.log))
  // or send to an analytics endpoint. Learn more: https://bit.ly/CRA-vitals
})();
