import { RouteConfig } from '~/shared/routes/route-names';

export const Notifi: RouteConfig<'notification'> = {
  list: {
    lazy: async () => {
      const { NotificationListPage } = await import('./notification-list/notification-list-page');
      return {
        Component: NotificationListPage,
      };
    },
  },
  setting: {
    lazy: async () => {
      const { NotificationSettingPage } = await import('./notification-setting/notification-setting-page');
      return {
        Component: NotificationSettingPage,
      };
    },
  },
};
