import { useCallback, useEffect, useRef } from 'react';
import { NavigateOptions, To, useLocation, useNavigate as _useNavigate } from 'react-router-dom';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { goBackWebview } from '~/shared/api/web-view';
import { isWalletRequiredRoute } from '~/shared/lib/utils/is-wallet-required-route';
import { PATHS, PathType } from '~/shared/routes/paths';
import { useWalletMissingAlert } from './use-wallet-missing-alert';

export type NavigateTo = PathType | -1 | 0 | To;
export const useNavigate = () => {
  const _navigate = _useNavigate();
  const location = useLocation();
  const lastLocationKeyRef = useRef(location.key);
  const didFallbackRef = useRef(false);
  const { showAlert } = useWalletMissingAlert();
  const { data: userRes } = useGetUserInfoQuery();
  const hasWallet = !!userRes?.tbCstmrMastr?.hasWallet;

  useEffect(() => {
    lastLocationKeyRef.current = location.key;
  }, [location.key]);

  // Memoize navigate function
  const navigate = useCallback(
    (to: NavigateTo, options?: NavigateOptions) => {
      if (!hasWallet && isWalletRequiredRoute(to.toString())) {
        showAlert();
        return;
      }
      _navigate(to as To, options);
    },
    [hasWallet, showAlert, _navigate], // Proper dependencies
  );

  // Memoize other nav functions
  const reload = useCallback(async () => {
    _navigate(0);
    return Promise.resolve();
  }, [_navigate]);

  const navigateBack = useCallback(() => {
    didFallbackRef.current = false;
    const startKey = lastLocationKeyRef.current;
    const startIdx = window.history.state?.idx;
    const isChildWindow = new URLSearchParams(window.location.search).has('isChildWindow');

    const fallback = () => {
      if (didFallbackRef.current) return;
      didFallbackRef.current = true;

      //새창의 첫페이지
      if (isChildWindow) {
        if (window.ReactNativeWebView && window.webViewBridge?.send) {
          window.webViewBridge.send('CLOSE_POPUP');
          return;
        }
        window.close();
        return;
      }

      if (window.ReactNativeWebView && window.webViewBridge?.send) {
        window.webViewBridge.send('CLOSE_POPUP');
        return;
      }
      _navigate(PATHS.home, { replace: true });
    };

    //기존
    goBackWebview(() => _navigate(-1), fallback);

    window.setTimeout(() => {
      if (didFallbackRef.current) return;
      const sameKey = lastLocationKeyRef.current === startKey;
      const sameIdx = typeof startIdx === 'number' ? window.history.state?.idx === startIdx : true;
      if (sameKey && sameIdx) {
        fallback();
      }
    }, 200);
  }, [_navigate]);

  return { navigate, navigateBack, reload };
};

export type VoucherNavigationState = {
  [key: string]: unknown;
};

export const useVoucherNavigation = () => {
  const { navigate } = useNavigate();

  const navigateToVoucherDetail = useCallback(
    (vouchId: string, state?: VoucherNavigationState) => {
      if (!vouchId) return;

      navigate(`${PATHS.voucher.voucherDetail}?vouchId=${vouchId}`, state ? { state } : undefined);
    },
    [navigate],
  );

  return { navigateToVoucherDetail };
};
