import { useThrottle } from '@toss/react';
import clsx from 'clsx';
import { motion, useAnimation } from 'framer-motion';
import { memo } from 'react';

type RefreshButtonProps = {
  onClick: () => void;
  children?: React.ReactNode;
  disabled?: boolean;
};
export const RefreshButton = memo(function RefreshButton({ onClick, children, disabled }: RefreshButtonProps) {
  const controls = useAnimation();
  const handleReset = useThrottle(async () => {
    if (disabled) return;
    try {
      await controls.start({
        rotate: 360,
        transition: { duration: 0.4 },
      });
      controls.set({ rotate: 0 });
      onClick?.();
    } catch (error) {
      console.error('Error during reset animation:', error);
      onClick?.();
    }
  }, 1000);

  return (
    <button type="button" onClick={handleReset} className="flex flex-row" disabled={disabled}>
      {children}
      <motion.div
        className={clsx('btn reset-btn', { 'cursor-not-allowed opacity-50': disabled })}
        animate={controls}
        initial={{ rotate: 0 }}
      >
        <span>reset</span>
      </motion.div>
    </button>
  );
});
