import { useStore } from '~/app/store/store';
import { StorageKeys } from '~/shared/config/local-storage';
import { getGlobalQueryClient } from '~/shared/config/query';

export const clearAuthData = () => {
  getGlobalQueryClient().clear();
  useStore.getState().authSlice.setJwt(null);
  useStore.getState().appConfigSlice.resetHasPushTokenSent();
  localStorage.removeItem(StorageKeys.RequestId);
};

export const kickOut = () => {
  location.href = '/';
};

export const clearAppData = () => {
  localStorage.removeItem(StorageKeys.RootStore);
  setTimeout(() => {
    clearAuthData();
  }, 0);
};
