import { BankCode } from '~/shared/@types/banking-code';
import { RELEASE_VERSION, ENABLE_REMITTANCE } from './environment';
import { AppConfigMap } from './types';

/**
 * Unified configuration for all environments
 * This replaces the separate environment-specific config files
 * (mockup, development, stage, production)
 */
export const createAppConfigMap = (): AppConfigMap => {
  const configMap: AppConfigMap = {} as AppConfigMap;

  // Generate configuration for each bank code
  Object.values(BankCode).forEach((bankCode) => {
    configMap[bankCode] = {
      BANK_CODE: bankCode,
      WEB_VERSION: RELEASE_VERSION,
      ENABLE_REMITTANCE: ENABLE_REMITTANCE,
      BANK_NAME: import.meta.env.VITE_APP_BANK_NAME,
      SHORT_BANK_NAME: import.meta.env.VITE_APP_SHORT_BANK_NAME,
    };
  });

  return configMap;
};
