import { TokenItem } from '~/entities/pin/api/dtos/types';
import { UserParams } from '~/entities/user/api/dtos/types';
import { TokenItemType } from '~/shared/api/dtos/enums';
import { appConfig } from '~/shared/config';

export const transformUserWithTokenList = (userInfo: UserParams) => {
  let index = 0;
  const tokenList: TokenItem[] = [];
  tokenList.push({
    id: `${index}`,
    type: TokenItemType.DC1,
    amt: userInfo?.dc1CoinAmt ?? 0,
    bankCd: appConfig.BANK_CODE ?? '',
  });

  index++;

  // 실증에서 DC2 사용하지 않음
  // coinList.push({
  //   id: `${index}`,
  //   type: CoinItemType.DC2,
  //   amt: userInfo?.dc2CoinAmt ?? 0,
  //   bankCd: config.BANK_CODE ?? '',
  // });

  // 실증에서 DC2 사용하지 않음
  // if (userInfo?.dc2CoinList?.length) {
  //   index++;
  //   userInfo?.dc2CoinList.map((coin, i) => {
  //     coinList?.push({
  //       id: `${index + i}`,
  //       type: CoinItemType.DC2,
  //       amt: coin.amt,
  //       bankCd: coin.bankCd,
  //     });
  //   });
  // }

  userInfo.tokenList = tokenList;
  return userInfo;
};

