import { ErrorBoundary, ErrorBoundaryGroup } from '@suspensive/react';
import { useQueryErrorResetBoundary } from '@tanstack/react-query';
import { PropsWithChildren } from 'react';
import { FallbackProps } from 'react-error-boundary';

type Props = PropsWithChildren<{
  FallbackComponent: React.ComponentType<FallbackProps>;
}>;

export const CommonErrorBoundary = (props: Props) => {
  const { children, FallbackComponent } = props;
  const { reset: queryReset } = useQueryErrorResetBoundary();

  return (
    <ErrorBoundaryGroup>
      <ErrorBoundary
        fallback={({ error, reset }) => <FallbackComponent error={error} resetErrorBoundary={reset} />}
        onReset={queryReset}
      >
        {children}
      </ErrorBoundary>
    </ErrorBoundaryGroup>
  );
};
