import { memo } from 'react';

type ErrorContainerProps = {
  isErrorPaddingPresent?: boolean;
  children: React.ReactNode;
};

export const ErrorContainer = memo(function ErrorContainer({ isErrorPaddingPresent, children }: ErrorContainerProps) {
  return <div className={isErrorPaddingPresent ? 'h-6' : undefined}>{children}</div>;
});
