import { useCallback } from 'react';
import { z } from 'zod';
import i18n from '~/shared/i18n/i18n';
import type { DialogProps } from '~/shared/ui/dialogs/dialog';

const errorResponseSchema = z.object({
  response: z
    .object({
      data: z
        .object({
          message: z.string().optional(),
        })
        .optional(),
    })
    .optional(),
});

export type ErrorWithResponse = z.infer<typeof errorResponseSchema>;

export const useErrorMessage = () => {
  const formatErrorMessage = useCallback((error: ErrorWithResponse): Partial<DialogProps> => {
    let message: Partial<DialogProps> = {
      message: i18n.t('validation:networkConnectionError'),
    };

    if (error?.response?.data?.message) {
      message = {
        message: error.response.data.message,
      };
    }

    return message;
  }, []);

  return {
    formatErrorMessage,
  };
};
