import { useCallback, useEffect } from 'react';
import { useShallow } from 'zustand/react/shallow';
import { useStore } from '~/app/store/store';

export const FONT_SIZE_CLASS = 'fs-large';

export const useLargeFontSizeStorage = () => {
  const [isLargeFontSizeEnabled, setIsLargeFontSizeEnabled, resetIsLargeFontSize] = useStore(
    useShallow((state) => [
      state.appConfigSlice.isLargeFontSizeEnabled,
      state.appConfigSlice.setIsLargeFontSizeEnabled,
      state.appConfigSlice.resetIsLargeFontSize,
    ]),
  );
  return {
    isLargeFontSizeEnabled,
    setIsLargeFontSizeEnabled,
    resetIsLargeFontSize,
  };
};

export const useLargeFontSize = () => {
  const { isLargeFontSizeEnabled, setIsLargeFontSizeEnabled } = useLargeFontSizeStorage();

  const setBodyLargeFontSize = () => {
    if (isLargeFontSizeEnabled) {
      document.body.classList.add(FONT_SIZE_CLASS);
    } else {
      document.body.classList.remove(FONT_SIZE_CLASS);
    }
  };

  const toggleFontSize = useCallback((shouldSwitch?: boolean) => {
    setIsLargeFontSizeEnabled((prev) => shouldSwitch ?? !prev);
  }, []);

  useEffect(() => {
    setBodyLargeFontSize();
  }, [isLargeFontSizeEnabled]);

  return {
    isLargeFontSizeEnabled,
    toggleFontSize,
  };
};
