import { Navigate, Outlet } from 'react-router-dom';
import { useStore } from '~/app/store/store';
import { useSubLayoutContext } from '~/widgets/sub-layout/use-sub-layout';
import { IS_MOCK_PHASE } from '~/shared/config/environment';
import { PATHS } from '~/shared/routes/paths';

export const ProtectedRoute = () => {
  const subLayoutContext = useSubLayoutContext();

  const token = IS_MOCK_PHASE ? true : useStore.getState().authSlice.jwt;
  return token ? <Outlet context={{ ...subLayoutContext }} /> : <Navigate to={PATHS.root} replace />;
};
