import { Suspense } from '@suspensive/react';
import { Fragment, ReactNode, useState } from 'react';
import { Outlet } from 'react-router-dom';
import { FullScreenLoading } from '~/widgets/loading/full-screen-loading';
import { Navigation } from '~/widgets/navigation';
import { PullToRefresh } from '~/widgets/pull-to-refresh/pull-to-refresh';
import { useNavigate } from '~/shared/lib/hooks';
import { useScrollToTop } from '~/shared/lib/hooks/use-scroll-to-top';

export type ContextType = {
  setOnBack: (onBack: () => void) => void;
  setHeaderTitle: (title: string) => void;
  setHeaderRight: (component: ReactNode) => void;
  setHeaderLeft: (component: ReactNode) => void;
  setIsPullToRefreshEnabled: (enabled: boolean) => void;
};

export const SubLayout = () => {
  const { reload } = useNavigate();
  useScrollToTop();
  const [onBack, setOnBack] = useState(undefined);
  const [headerTitle, setHeaderTitle] = useState('');
  const [headerRight, setHeaderRight] = useState(undefined);
  const [headerLeft, setHeaderLeft] = useState(undefined);
  const [isPullToRefreshEnabled, setIsPullToRefreshEnabled] = useState(false);

  return (
    <PullToRefresh onRefresh={reload} isPullable={isPullToRefreshEnabled}>
      <Fragment>
        <Navigation onBack={onBack} headerTitle={headerTitle} headerRight={headerRight} headerLeft={headerLeft} />
        <main className="main-content">
          <Suspense fallback={<FullScreenLoading />}>
            <Outlet
              context={{
                setOnBack,
                setHeaderTitle,
                setHeaderRight,
                setHeaderLeft,
                setIsPullToRefreshEnabled,
              }}
            />
          </Suspense>
        </main>
      </Fragment>
    </PullToRefresh>
  );
};
