import { format } from 'date-fns';
import { StorageKeys } from '~/shared/config/local-storage';

export const setLocalStorage = (key: StorageKeys, value: any) => {
  if (!key) return false;

  if (typeof value === 'object') {
    window.localStorage.setItem(key, JSON.stringify(value));
  } else {
    window.localStorage.setItem(key, value);
  }

  return true;
};

export const getLocalStorage = (key: StorageKeys) => {
  if (!key) return;
  const ret = window?.localStorage?.getItem(key);

  try {
    return ret && JSON.parse(ret);
  } catch (error) {
    return ret;
  }
};

export const parseToDate = (
  date: string | number | Date | string[] | number[] | null | undefined,
  strFormat?: string,
): string => {
  if (!date) return '';
  if (!strFormat) strFormat = 'yyyy.MM.dd HH:mm:ss';
  let parse = '';
  switch (typeof date) {
    case 'string':
      try {
        return format(new Date(date), strFormat);
      } catch (error) {
        return date;
      }

    case 'number':
    case 'object':
      let dDate = null;
      if (date instanceof Date || typeof date === 'number') {
        dDate = new Date(date);
      } else if (date instanceof Array) {
        if (date.length === 6)
          dDate = new Date(
            Number(date[0]),
            Number(date[1]) - 1,
            Number(date[2]),
            Number(date[3]),
            Number(date[4]),
            Number(date[5]),
          );
        else if (date.length === 5)
          dDate = dDate = new Date(
            Number(date[0]),
            Number(date[1]) - 1,
            Number(date[2]),
            Number(date[3]),
            Number(date[4]),
          );
        else if (date.length === 4)
          dDate = dDate = new Date(Number(date[0]), Number(date[1]) - 1, Number(date[2]), Number(date[3]));
        else if (date.length === 3) dDate = dDate = new Date(Number(date[0]), Number(date[1]) - 1, Number(date[2]));
        else if (date.length === 2) dDate = dDate = new Date(Number(date[0]), Number(date[1]) - 1);
        else if (date.length === 1) dDate = new Date(Number(date[0]));
      }

      if (dDate) parse = format(dDate, strFormat);

      return parse;
  }
};
