import { Description, Dialog as _Dialog, DialogPanel, DialogTitle, Transition } from '@headlessui/react';
import { useBlocker } from '@use-blocker';
import { useBridge } from '@webview-bridge/react';
import { Fragment, isValidElement, memo, ReactNode, useCallback, useContext, useMemo } from 'react';
import { UNSAFE_DataRouterContext } from 'react-router-dom';
import i18n from '~/shared/i18n/i18n';
import { DialogButtons } from '~/shared/ui/dialogs/dialog-buttons';
import { bridge } from '~/bridge';

export type DialogMessage = string | ReactNode | object;

export type DialogProps = {
  open: boolean;
  onConfirmClick?: () => void | Promise<void>;
  onCancelClick?: () => void | Promise<void>;
  children?: ReactNode;
  title?: string | ReactNode;
  message?: DialogMessage;
  shouldCloseOnBackdropClick?: boolean;
  buttonLabel?: string[];
  onClose: () => void;
  fullScreenMode?: boolean;
  afterLeave: () => void;
  overlayClassName?: string;
  layerIndex?: number;
};

const isJsonObject = (value: unknown): value is object => {
  if (typeof value === 'string') return false;
  if (isValidElement(value)) return false;

  return typeof value === 'object' && value !== null;
};

export const Dialog = memo(function Dialog({
  open = false,
  onConfirmClick,
  onCancelClick,
  children,
  title,
  message,
  shouldCloseOnBackdropClick = false,
  buttonLabel = [i18n.t('confirm')],
  onClose,
  afterLeave,
  fullScreenMode = false,
  overlayClassName,
  layerIndex,
}: DialogProps) {
  const { nativeDialog, resetNativeDialog } = useBridge(bridge.store, (state) => state);
  const hasCustomLayerIndex = typeof layerIndex === 'number';

  const dataRouter = useContext(UNSAFE_DataRouterContext);
  const whenToBlock = useCallback(() => open, [open]);
  // useBlocker는 데이터 라우터가 있을 때만 실행
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const blocker = dataRouter ? useBlocker(whenToBlock) : null;
  const nativeMessage = nativeDialog?.message;
  const displayMessage = nativeMessage || message;

  const shouldRenderAsJson = useMemo(
    () => displayMessage !== undefined && isJsonObject(displayMessage),
    [displayMessage],
  );
  const handleClose = useCallback(() => {
    resetNativeDialog?.();
    onClose();
  }, []);
  const handleConfirm = useCallback(() => {
    blocker?.proceed?.();
    onConfirmClick?.();
    handleClose();
  }, [blocker]);
  const handleCancel = useCallback(() => {
    blocker?.reset?.();
    onCancelClick?.();
    handleClose();
  }, [blocker]);

  return (
    <Transition
      afterLeave={afterLeave}
      show={open}
      as={Fragment}
      enter="ease-out duration-300"
      enterFrom="opacity-0"
      enterTo="opacity-100"
      leave="ease-in duration-100"
      leaveFrom="opacity-100"
      leaveTo="opacity-0"
    >
      <_Dialog onClose={shouldCloseOnBackdropClick ? onClose : () => null} static={!shouldCloseOnBackdropClick}>
        {/* The backdrop, rendered as a fixed sibling to the panel container */}
        <div
          className={`fixed inset-0 z-[60] bg-black/50 ${overlayClassName ?? ''}`}
          style={hasCustomLayerIndex ? { zIndex: layerIndex - 10 } : undefined}
          aria-hidden="true"
        />
        <div
          className={`fixed inset-0 z-[70] flex w-screen ${fullScreenMode ? '' : 'items-center justify-center p-[30px]'} ${overlayClassName ?? ''}`}
          style={hasCustomLayerIndex ? { zIndex: layerIndex } : undefined}
        >
          <DialogPanel
            as="div"
            data-testid="dialog-panel"
            className={`z-[80] mx-auto w-full bg-white ${fullScreenMode ? 'env-top flex h-screen max-h-screen min-h-screen flex-auto flex-col overflow-y-auto' : 'rounded-[10px]'} ${overlayClassName ?? ''}`}
            style={hasCustomLayerIndex ? { zIndex: layerIndex + 10 } : undefined}
          >
            <div className={fullScreenMode || children ? 'flex flex-auto' : 'alert-msg'}>
              {title && (
                <DialogTitle as="div" className="font-bold">
                  {title}
                </DialogTitle>
              )}
              {displayMessage &&
                (shouldRenderAsJson ? (
                  <Description as="div" className="flex flex-auto">
                    <pre className="max-h-[50vh] w-full overflow-auto whitespace-pre-wrap break-all rounded bg-gray-50 p-3 text-left text-xs leading-5">
                      {JSON.stringify(displayMessage, null, 2)}
                    </pre>
                  </Description>
                ) : (
                  <Description as="div" className="flex flex-auto whitespace-pre-line break-all">
                    {displayMessage}
                  </Description>
                ))}

              {children}
            </div>
            {/* render buttonLabel */}
            {!fullScreenMode && (
              <DialogButtons buttonLabel={buttonLabel} onCancel={handleCancel} onConfirm={handleConfirm} />
            )}
          </DialogPanel>
        </div>
      </_Dialog>
    </Transition>
  );
});
