import { AxiosPromise, AxiosResponse } from 'axios';
import { CBDCAxiosError } from '~/shared/@types/error';

export const resultify = async <T = unknown>(promiseObj: AxiosPromise<T>): Promise<T> => {
  try {
    const result: AxiosResponse<T> = await promiseObj;
    return result?.data !== undefined && result?.data !== null ? result.data : (result as T);
  } catch (error: unknown) {
    const axiosError = error as CBDCAxiosError;
    console.error(
      `${
        axiosError.response?.status ? `[${axiosError.response.status}], ` : ''
      }${JSON.stringify(axiosError.response?.data)}`,
    );
    throw error;
  }
};
