import { FallbackProps } from 'react-error-boundary';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { parseError } from '~/shared/lib/utils/error-message';
import { Dialog } from '~/shared/ui/dialogs/dialog';

type CommonErrorProps = FallbackProps & {
  height?: number;
};

export const APIErrorFallback = ({ error, resetErrorBoundary }: CommonErrorProps) => {
  const { navigateBack } = useNavigate();
  const parsedError = parseError(error);

  const handleCancel = () => {
    navigateBack();
    resetErrorBoundary();
  };

  return (
    <Dialog
      afterLeave={() => null}
      open={true}
      onClose={() => null}
      onConfirmClick={resetErrorBoundary}
      onCancelClick={handleCancel}
      title={parsedError.title}
      message={parsedError.message}
      buttonLabel={[i18n.t('cancel'), i18n.t('retry')]}
    />
  );
};
