import { lens } from '@dhmk/zustand-lens';
import { useStore } from '~/app/store/store';
import { resetUserInfo } from '~/entities/user/api/use-get-cstmr-query';

export type AuthState = {
  jwt: string | null | undefined;
  setJwt: (jwt: string | null | undefined) => void;
  resetAuth: () => void;
};

const initialState = {} as AuthState;

export const createAuthSlice = lens<AuthState>((set) => ({
  ...initialState,
  setJwt: (jwt: string | null | undefined) => {
    set((state: AuthState) => {
      return {
        ...state,
        jwt,
      };
    });
  },
  resetAuth: () => {
    resetUserInfo();
    useStore.getState().authSlice.setJwt(null);
    useStore.getState().appConfigSlice.resetHasPushTokenSent();
  },
}));
