import { useMemo } from 'react';
import { useStore } from '~/app/store/store';
import { appConfig } from '~/shared/config';

export const useAppVersion = () => {
  const appVersion = useStore((state) => state.appConfigSlice.appVersion);
  return appVersion;
};

export const webVersion = appConfig.WEB_VERSION.replace(/\b(\d+)(?:\.0\.0)?\b/g, '$1');
export const useFullVersion = () => {
  const appVersion = useAppVersion();
  const fullVersion = useMemo(() => `${appVersion}.${webVersion}`, [appVersion]);
  return { fullVersion };
};
