import { useBodyClass } from '@toss/react';
import { appConfig } from '~/shared/config';
import { useRouterListener } from '~/shared/lib/hooks';
import { useLargeFontSize } from '~/shared/lib/hooks/use-app-font-size';
import { PATHS } from '~/shared/routes/paths';

const HOME_BACKGROUND_COLOR = 'home-bg-color';
export const useInitTheme = () => {
  useLargeFontSize();
  useBodyClass(appConfig.BANK_CODE);
  useRouterListener((state) => {
    if (state?.location.pathname === PATHS.home) {
      document.body.classList.add(HOME_BACKGROUND_COLOR);
    } else {
      document.body.classList.remove(HOME_BACKGROUND_COLOR);
    }
  });
};
